export function renderHome({data:D,esc,asset,icon,route,dateParts,futureEvents,projectArt}){
  const h=D.home;
  const button=(label,url,outline=false)=>`<a class="home-button${outline?' home-button-outline':''}" href="${esc(url)}">${esc(label)}${outline?'':icon('arrow',18)}</a>`;
  const heading=s=>`<div class="home-heading"><div class="home-heading-top"><div><p class="home-eyebrow">${esc(s.label)}</p><h2>${esc(s.title)}</h2></div>${s.linkLabel?`<a class="home-heading-link" href="${esc(s.linkUrl)}">${esc(s.linkLabel)} →</a>`:''}</div><hr class="home-heading-rule">${s.description?`<p class="home-heading-description">${esc(s.description)}</p>`:''}</div>`;
  const event=h.featuredEvent.slug?D.events.find(e=>e.slug===h.featuredEvent.slug):futureEvents()[0];
  const eventSection=()=>{
    if(!event)return `<section class="home-featured-event" id="featured-event"><div class="home-container home-event-inner"><div class="home-event-copy"><p class="home-eyebrow">${esc(h.featuredEvent.label)}</p><h2>Events and seminars</h2><p class="home-event-description">Upcoming events will be listed here.</p></div>${button('Browse events','/events')}</div></section>`;
    const d=dateParts(event);
    return `<section class="home-featured-event" id="featured-event">${asset(event.image)?`<img class="home-event-image" src="${esc(asset(event.image))}" alt="" loading="lazy">`:''}<span class="home-event-shade" aria-hidden="true"></span><div class="home-container home-event-inner"><div class="home-event-copy"><p class="home-eyebrow">${esc(h.featuredEvent.label)}</p><h2><a href="${route('events',event.slug)}">${esc(event.title)}</a></h2><div class="home-event-meta"><span>${icon('calendar',16)}${esc(d.date)} · ${esc(d.time)} (${esc(event.timezone)})</span><span>${icon('globe',16)}${esc(event.location||'Online')}</span></div><p class="home-event-description">${esc(event.summary)}</p></div>${button(h.featuredEvent.buttonLabel,route('events',event.slug))}</div></section>`;
  };
  const publication=p=>{
    const project=D.projects.find(item=>item.papers.includes(p.id));
    const url=asset(p.url||p.pdf);
    return `<article class="home-publication">${project?`<a class="home-publication-topic" href="${route('projects',project.slug)}">${esc(project.title)}</a>`:''}<h3><a href="/publications?q=${encodeURIComponent(p.title)}">${esc(p.title)}</a></h3><p>${esc(p.authors)}</p><p class="home-publication-venue">${esc(p.venue)} · ${esc(p.year)}</p>${url?`<a class="home-publication-read" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Read paper ${icon('arrow',16)}</a>`:'<span class="coming">Paper link coming soon</span>'}</article>`;
  };
  return `<div class="home-page">
    <section class="home-hero" id="home-hero"><span class="home-hero-shade" aria-hidden="true"></span><div class="home-container home-hero-inner"><div class="home-hero-copy"><p class="home-affiliation">${icon('globe',14)}${esc(h.affiliation)}</p><h1>${esc(h.heroTitle)}</h1><p class="home-hero-description">${esc(h.heroDescription)}</p><div class="home-actions">${button(h.primaryAction.label,h.primaryAction.url)}${button(h.secondaryAction.label,h.secondaryAction.url,true)}</div><nav class="home-lab-links" aria-label="Explore our labs">${D.labs.map(l=>`<a href="${route('labs',l.slug)}">${icon(l.icon==='atom'?'atom':'bolt',15)}${esc(l.shortTitle||l.title)}</a>`).join('')}</nav></div></div></section>
    <div class="home-stats-band" id="research-statistics"><div class="home-container"><dl class="home-stats">${D.organization.stats.map(s=>`<div class="home-stat"><dd>${esc(s.value)}</dd><dt>${esc(s.label)}</dt></div>`).join('')}</dl></div></div>
    <div class="home-container home-introduction" id="lab-introduction"><div><p>${esc(h.introduction)}</p></div></div>
    <section class="home-container home-section" id="research-areas">${heading(h.whatWeDo)}<div class="home-focus-grid">${h.whatWeDo.areas.map(a=>`<article class="home-focus"><span class="home-focus-icon">${icon(a.icon,28)}</span><h3><a href="${esc(a.url)}">${esc(a.title)}</a></h3><p>${esc(a.description)}</p></article>`).join('')}</div></section>
    ${eventSection()}
    <div class="home-research"><section class="home-container home-section" id="research-initiatives">${heading(h.research)}<div class="home-project-grid">${D.projects.map(p=>`<a class="home-project" href="${route('projects',p.slug)}"><div class="home-project-visual">${projectArt(p)}</div><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><span class="home-project-link">${esc(h.research.itemLinkLabel)}${icon('arrow',16)}</span></a>`).join('')}</div><a class="home-funding-link" href="/projects?filter=funded">${esc(h.research.fundedLabel)} →</a></section></div>
    <div class="home-publications"><section class="home-container home-section" id="recent-publications">${heading(h.publications)}<div class="home-publication-grid">${D.publications.slice(0,h.publications.limit||4).map(publication).join('')}</div></section></div>
    <section class="home-contact-band" id="research-collaboration"><div class="home-container home-contact-inner"><div><h2>${esc(h.collaboration.title)}</h2><p>${esc(h.collaboration.description)}</p></div>${button(h.collaboration.buttonLabel,h.collaboration.buttonUrl)}</div></section>
  </div>`;
}

export function renderSiteFooter({data:D,esc,safeUrl,icon,brand}){
  const o=D.organization;
  const labels={linkedin:'LinkedIn',youtube:'YouTube',github:'GitHub',facebook:'Facebook'};
  return `<div class="home-container home-footer-inner"><div class="home-footer-grid"><div class="home-footer-brand">${brand()}<p>${esc(o.tagline)}</p><div class="home-socials">${Object.entries(o.social).map(([kind,url])=>safeUrl(url)?`<a class="home-social" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer" aria-label="${labels[kind]||esc(kind)}">${icon(kind,19)}</a>`:`<span class="home-social" title="${labels[kind]||esc(kind)} link coming soon" aria-label="${labels[kind]||esc(kind)} link coming soon">${icon(kind,19)}</span>`).join('')}</div><form data-form="newsletter"><label class="footer-newsletter-label" for="newsletter-email">Lab updates</label><div class="newsletter"><input id="newsletter-email" name="email" type="email" required autocomplete="email" placeholder="Your email address"><button aria-label="Join newsletter">${icon('arrow',17)}</button></div><p class="newsletter-note">${o.newsletterEndpoint?'Research updates, courses, and upcoming events.':'Demo: your interest is saved on this device.'}</p></form></div><div class="home-footer-column"><h3>Explore</h3><div class="home-footer-links">${D.navigation.filter(n=>n.url!=='/').map(n=>`<a href="${esc(n.url)}">${esc(n.label)}</a>`).join('')}<a href="/publications">Publications</a></div></div><div class="home-footer-column"><h3>Contact</h3><div class="home-footer-links"><p>${esc(o.address)}</p><a href="mailto:${esc(o.email)}">${esc(o.email)}</a><a href="/contact">Contact the lab</a><a href="/registrations">My registrations</a></div></div></div><div class="home-footer-bottom"><p>&copy; ${new Date().getFullYear()} ${esc(o.name)}. All rights reserved.</p><p>${esc(D.home.affiliation)}</p></div>${D.demo?'<p class="home-footer-demo">Demo content. People, affiliations, and research records shown are illustrative.</p>':''}</div>`;
}
